import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws Unknown tool for unregistered tools ([validated by](./registry.test.ts#L4))', () => {
    const registry = new ToolRegistry();
    expect(() => registry.execute('nonexistent', {})).rejects.toThrow('Unknown tool: nonexistent');
  });

  it('passes valid input through to executor unchanged including extra properties ([validated by](./registry.test.ts#L9))', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];

    registry.register(
      {
        name: 'accept_input',
        description: 'Accepts input',
        inputSchema: {
          type: 'object',
          properties: {name: {type: 'string'}},
          required: ['name'],
        },
      },
      async input => {
        executorInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('accept_input', {name: 'test', extra: 'field'});

    expect({
      result: response.result,
      inputCount: executorInputs.length,
      hasExtra: executorInputs[0]?.extra === 'field',
    }).toEqual({
      result: 'ok',
      inputCount: 1,
      hasExtra: true,
    });
  });
});

